---

## 5️⃣ Component Architecture

| Feature | Suggested Components | Notes |
|---------|----------------------|-------|
| **Layout** | `Header`, `Footer`, `Sidebar` (admin) | Wrap with `Layout` component |
| **Product** | `ProductCard`, `ProductList`, `ProductDetail` | Use `next/image` for lazy loading |
| **Cart** | `CartItem`, `CartSummary`, `CheckoutForm` | Persist cart in localStorage + Redux |
| **Auth** | `LoginForm`, `RegisterForm`, `ProfilePage` | Use NextAuth.js for OAuth + JWT |
| **Admin** | `AdminDashboard`, `ProductTable`, `OrderTable` | Protect routes with middleware |
| **Utilities** | `Button`, `Input`, `Modal`, `Toast` | Build a component library or use Radix UI |

> **Tip:** Keep components small and reusable. Use TypeScript interfaces for props.

---

## 6️⃣ State Management (Redux Toolkit)

```ts
// store.ts
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from './slices/cartSlice';
import authReducer from './slices/authSlice';

export const store = configureStore({
  reducer: {
    cart: cartReducer,
    auth: authReducer,
  },
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
```

```ts
// slices/cartSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface CartItem {
  id: string;
  quantity: number;
  price: number;
}

interface CartState {
  items: Record<string, CartItem>;
}

const initialState: CartState = { items: {} };

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart(state, action: PayloadAction<CartItem>) {
      const { id, quantity, price } = action.payload;
      if (state.items[id]) {
        state.items[id].quantity += quantity;
      } else {
        state.items[id] = { id, quantity, price };
      }
    },
    removeFromCart(state, action: PayloadAction<string>) {
      delete state.items[action.payload];
    },
    clearCart(state) {
      state.items = {};
    },
  },
});

export const { addToCart, removeFromCart, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

---

## 7️⃣ API Integration (React Query)

```ts
// hooks/useProducts.ts
import { useQuery } from '@tanstack/react-query';
import axios from 'axios';

export const fetchProducts = async () => {
  const { data } = await axios.get('/api/products');
  return data;
};

export const useProducts = () =>
  useQuery(['products'], fetchProducts);
```

```tsx
// pages/index.tsx
import { useProducts } from '../hooks/useProducts';
import ProductCard from '../components/ProductCard';

export default function Home() {
  const { data, isLoading, error } = useProducts();

  if (isLoading) return <p>Loading…</p>;
  if (error) return <p>Error loading products.</p>;

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
      {data.map((product) => (
        <ProductCard key={product.id} product={product} />
      ))}
    </div>
  );
}
```

