## 8️⃣ Authentication (NextAuth.js)

```bash
npm i next-auth
```

```ts
// pages/api/auth/[...nextauth].ts
import NextAuth from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';

export default NextAuth({
  providers: [
    CredentialsProvider({
      name: 'Credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials) {
        // Call your own API or database
        const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/login`, {
          method: 'POST',
          body: JSON.stringify(credentials),
          headers: { 'Content-Type': 'application/json' },
        });
        const user = await res.json();
        if (res.ok && user) {
          return user;
        }
        return null;
      },
    }),
  ],
  session: { strategy: 'jwt' },
  callbacks: {
    async jwt({ token, user }) {
      if (user) token.id = user.id;
      return token;
    },
    async session({ session, token }) {
      session.user.id = token.id as string;
      return session;
    },
  },
});
```

Use `useSession()` hook in components to guard routes or show user info.

---

## 9️⃣ Payment Integration

| Provider | Integration Steps | Notes |
|----------|-------------------|-------|
| Stripe | Create Checkout Session via API route, redirect to Stripe Checkout | Use `stripe-node` SDK |
| PayPal | Use PayPal JS SDK, create order via API route | Sandbox mode for testing |
| Braintree | Use Braintree SDK, generate client token | Good for recurring payments |

**Example: Stripe Checkout**

```ts
// pages/api/checkout_sessions.ts
import { NextApiRequest, NextApiResponse } from 'next';
import Stripe from 'stripe';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2023-10-16',
});

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();

  const { items } = req.body; // [{priceId, quantity}]
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: items.map((i: any) => ({
        price: i.priceId,
        quantity: i.quantity,
      })),
      mode: 'payment',
      success_url: `${process.env.NEXT_PUBLIC_SITE_URL}/success`,
      cancel_url: `${process.env.NEXT_PUBLIC_SITE_URL}/cancel`,
    });
    res.status(200).json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}
```

```tsx
// components/CheckoutButton.tsx
import { useRouter } from 'next/router';
import { useMutation } from '@tanstack/react-query';
import axios from 'axios';

export default function CheckoutButton({ items }) {
  const router = useRouter();
  const mutation = useMutation(
    () => axios.post('/api/checkout_sessions', { items }),
    {
      onSuccess: ({ data }) => router.push(data.url),
    }
  );

  return (
    <button
      onClick={() => mutation.mutate()}
      disabled={mutation.isLoading}
      className="bg-indigo-600 text-white px-4 py-2 rounded"
    >
      {mutation.isLoading ? 'Processing…' : 'Checkout'}
    </button>
  );
}
```

